import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader fr = new FastReader();
        PrintWriter pw = new PrintWriter(System.out);
        int n = fr.nextInt();
        int[] a = new int[3];
        int[] b = new int[3];
        for (int i = 0; i < 3; i++) a[i] = fr.nextInt();
        for (int i = 0; i < 3; i++) b[i] = fr.nextInt();
        int max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        int min = Integer.MAX_VALUE;
        List<int[]> pairs = new ArrayList<>();
        pairs.add(new int[]{0, 0});
        pairs.add(new int[]{1, 1});
        pairs.add(new int[]{2, 2});
        pairs.add(new int[]{0, 2});
        pairs.add(new int[]{1, 0});
        pairs.add(new int[]{2, 1});
        min = solve(pairs, 0, a, b, min);
        pw.println(min + " " + max);
        pw.close();
    }

    static int solve(List<int[]> pairs, int idx, int[] a, int[] b, int min) {
        int[] ca = a.clone();
        int[] cb = b.clone();
        for (int[] p : pairs) {
            int m = Math.min(ca[p[0]], cb[p[1]]);
            cb[p[1]] -= m;
            ca[p[0]] -= m;
        }
        int sum = 0;
        for (int i = 0; i < 3; i++) sum += ca[i];
        min = Math.min(min, sum);
        for (int i = idx; i < pairs.size(); i++) {
            Collections.swap(pairs, i, idx);
            min = solve(pairs, idx + 1, a, b, min);
            Collections.swap(pairs, i, idx);
        }
        return min;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
